"use strict";(self.webpackChunkdammy=self.webpackChunkdammy||[]).push([[76],{1462:(n,a,s)=>{s.r(a),s.d(a,{data:()=>e});const e={key:"v-6af80077",path:"/ja/overview/",title:"概要",lang:"ja-JP",frontmatter:{},excerpt:"",headers:[{level:2,title:"dammy とは？",slug:"dammy-とは",children:[{level:3,title:"できること",slug:"できること",children:[]}]},{level:2,title:"使用例",slug:"使用例",children:[]}],filePathRelative:"ja/overview/README.md",git:{updatedTime:1779339404e3,contributors:[{name:"ontheroadjp",email:"dev@ontheroad.jp",commits:3}]}}},1269:(n,a,s)=>{s.r(a),s.d(a,{default:()=>t});const e=(0,s(6252).uE)('<h1 id="概要" tabindex="-1"><a class="header-anchor" href="#概要" aria-hidden="true">#</a> 概要</h1><h2 id="dammy-とは" tabindex="-1"><a class="header-anchor" href="#dammy-とは" aria-hidden="true">#</a> dammy とは？</h2><p><strong>dammy</strong> は、テストや開発に必要なダミーファイルとディレクトリツリーを即座に生成する Bash スクリプトです。</p><p><code>mkdir</code> や <code>touch</code> を何度も打ち込んでテスト環境を手作りする作業は面倒で、ミスも起きやすいもの。dammy を使えば、そうした手間をコマンド一発で解消できます。</p><h3 id="できること" tabindex="-1"><a class="header-anchor" href="#できること" aria-hidden="true">#</a> できること</h3><ul><li><strong>テスト用の各種ダミーファイルを作成</strong> — ランダムな名前のファイルを好きな数だけ一気に生成。拡張子は自由に指定できます。</li><li><strong>ディレクトリ階層を自在に作成</strong> — 深い入れ子構造のディレクトリも自動で作成。事前に親ディレクトリを用意する必要はありません。</li><li><strong>特殊文字列を用いたファイル名・ディレクトリ名を作成</strong> — 記号・空白・全角文字（日本語）を含むファイル名を生成できます。ファイル名処理のエッジケース検証に最適です。</li><li><strong>Web 開発用のダミー画像を作成</strong> — 画像フォーマット（jpg, png, gif など）を指定すると、ImageMagick を使って実際の画像ファイルを生成します。グレー一色の背景に解像度が中央に表記されたシンプルな画像で、モックアップやフロントエンドのテストにすぐ使えます。</li><li><strong>作成前にプレビュー</strong> — <code>--cold-run</code> フラグを付けると、実際にはファイルを生成せず、作成される予定のツリー構造だけを表示して確認できます。</li></ul><h2 id="使用例" tabindex="-1"><a class="header-anchor" href="#使用例" aria-hidden="true">#</a> 使用例</h2><p>このコマンドを一発実行するだけで、</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>dammy.sh hoge/<span class="token punctuation">{</span>foo,bar<span class="token punctuation">}</span>/piyo -n <span class="token number">3</span> --each --with-whitespace\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br></div></div><p>以下のようなディレクトリツリーが即座に構築されます。</p><div class="language-text ext-text line-numbers-mode"><pre class="language-text"><code>hoge\n├── ) R a Y A .txt\n├── H t 8 9 h .txt\n├── \\ U X , ! .txt\n├── bar\n│   ├── ! + w 2 q .txt\n│   ├── , ) R ; c .txt\n│   ├── d P 9 6 i .txt\n│   └── piyo\n│       ├── % U 2 P L .txt\n│       ├── 5 R J j c .txt\n│       └── O S : 3 E .txt\n├── d M 6 2 x .txt\n├── foo\n│   ├── $ A P H _ .txt\n│   ├── J Z d &#39; a .txt\n│   ├── i W S _ 1 .txt\n│   └── piyo\n│       ├── : L w &amp; I .txt\n│       ├── A e @ j &amp; .txt\n│       └── r W 2 * ( .txt\n├── v @ R q j .txt\n└── y g R , 9 .txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div>',11),r={},t=(0,s(3744).Z)(r,[["render",function(n,a){return e}]])},3744:(n,a)=>{a.Z=(n,a)=>{const s=n.__vccOpts||n;for(const[n,e]of a)s[n]=e;return s}}}]);